<script setup lang="ts">
import{onMounted}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute}from'vue-router';import ProcurementSubnav from'../components/ProcurementSubnav.vue';import{useProcurementStore}from'../runtime/procurement-store';import'./procurement-views.css';const store=useProcurementStore(),route=useRoute();const{selectedSupplier:supplier,loading,error,saving,canWrite}=storeToRefs(store);onMounted(()=>store.loadSupplier(String(route.params.id)))
</script>
<template><section class="procurement-page"><header class="procurement-header"><div><RouterLink to="/procurement/suppliers">← 返回供应商</RouterLink><h1>{{supplier?.name??'供应商详情'}}</h1><p>{{supplier?.code}}</p></div><div v-if="supplier&&canWrite"><RouterLink class="pur-button" :to="`/procurement/suppliers/${supplier.id}/edit`">编辑</RouterLink> <button class="pur-button" :class="{danger:supplier.status==='enabled'}" :disabled="saving" @click="store.toggleSupplier(supplier)">{{supplier.status==='enabled'?'停用':'启用'}}</button></div></header><ProcurementSubnav/><div v-if="error" class="procurement-state error">{{error}}</div><div v-else-if="loading" class="procurement-state">正在加载供应商…</div><template v-else-if="supplier"><div class="procurement-detail"><section class="procurement-panel"><h2>基本资料</h2><dl class="procurement-definition"><div><dt>供应商编码</dt><dd>{{supplier.code}}</dd></div><div><dt>状态</dt><dd><span class="pur-status" :class="supplier.status">{{supplier.status==='enabled'?'启用':'停用'}}</span></dd></div><div><dt>交易类型</dt><dd>{{supplier.tradeType==='purchase'?'购销':'代销'}}</dd></div><div><dt>供货方式</dt><dd>{{({warehouse:'入仓',direct:'直送',both:'均可'}as const)[supplier.deliveryMode]}}</dd></div><div><dt>联系人</dt><dd>{{supplier.contactName}} · {{supplier.contactPhone}}</dd></div><div><dt>地址</dt><dd>{{supplier.address??'—'}}</dd></div><div><dt>开户行</dt><dd>{{supplier.bankName??'—'}}</dd></div><div><dt>银行账号</dt><dd>{{supplier.bankAccount??'—'}}</dd></div><div><dt>外部账号</dt><dd><span class="pur-status unavailable">未接入</span></dd></div><div><dt>版本</dt><dd>v{{supplier.version}}</dd></div></dl></section><aside class="procurement-panel"><h2>操作说明</h2><p>停用后不能用于新采购，但既有供货关系和日志会保留。</p><p>恢复供应商不会自动恢复已经停用的供货关系。</p><RouterLink class="pur-button" :to="`/procurement/supplier-products?supplierId=${supplier.id}`">查看供货商品</RouterLink></aside></div><section class="procurement-panel" style="margin-top:12px"><h2>供货关系（{{supplier.relations.length}}）</h2><div v-if="!supplier.relations.length">暂无供货关系</div><div v-else class="procurement-table-wrap"><table class="procurement-table"><thead><tr><th>商品 / SKU</th><th>采购单位</th><th>供应价</th><th>首选</th><th>关系状态</th></tr></thead><tbody><tr v-for="row in supplier.relations" :key="row.id"><td>{{row.productNameSnapshot}}<small>{{row.skuCodeSnapshot}} · {{row.specificationSnapshot}}</small></td><td>{{row.procurementUnitNameSnapshot}}<small>换算 {{row.procurementUnitRateMilli/1000}}</small></td><td class="pur-money">¥{{(row.supplyPriceCents/100).toFixed(2)}}</td><td>{{row.preferred?'是':'否'}}</td><td><span class="pur-status" :class="row.status">{{row.status==='enabled'?'启用':'停用'}}</span></td></tr></tbody></table></div></section><section class="procurement-panel" style="margin-top:12px"><h2>操作日志</h2><p v-if="!supplier.auditLogs.length">暂无操作日志</p><p v-for="log in supplier.auditLogs" :key="log.id"><strong>{{log.action}}</strong> · {{log.detail}} <small>{{log.createdAt}}</small></p></section></template></section></template>
